riction.", "children": [{"id": "cda39091-7a0b-4907-acd9-7492347ca959", "type": "subtopic", "title": "Kidney function and assessment", "description": "Students connect filtration, fluid and electrolyte regulation, and acid–base balance to nutrition.", "children": [{"id": "254c8de3-de80-4f64-80d7-fa069cfb65e1", "type": "concept", "title": "AKI versus CKD, eGFR and albuminuria trends, diabetes/hypertension, and progression"}, {"id": "d5f6f23f-f6c5-49f2-986b-c7d22c26fa07", "type": "concept", "title": "Volume status, blood pressure, urine output, appetite, symptoms, and medication review"}, {"id": "a69bc273-a6aa-4a3b-b231-545a46d68c69", "type": "concept", "title": "Potassium, phosphorus, bicarbonate, calcium/PTH context, anemia, and laboratory limitations"}]}, {"id": "238d7040-e988-4e59-bd26-8d5c79966c52", "type": "subtopic", "title": "Nutrition priorities by stage", "description": "Students balance adequacy, metabolic goals, and preservation of function.", "children": [{"id": "d6646e38-4959-4dd4-82c4-6cabaf063a16", "type": "concept", "title": "Energy and protein context before dialysis; sodium and blood-pressure management"}, {"id": "48854116-61e9-4c22-a818-e2fa08cab44e", "type": "concept", "title": "Potassium and phosphorus individualized to laboratory trends and food sources"}, {"id": "636f36e9-b1aa-4cc6-ab12-24860e03ae4a", "type": "concept", "title": "Plant-forward patterns, food additives, labels, diabetes integration, and cultural preferences"}]}, {"id": "febd7517-cc08-4c0d-8977-218c58dc3c25", "type": "subtopic", "title": "Safety and referral", "description": "Students recognize when kidney nutrition exceeds introductory scope.", "children": [{"id": "7396e7f5-c86a-4022-b7b3-3b881fb182e1", "type": "concept", "title": "Hyperkalemia symptoms/context, rapidly changing kidney function, severe fluid issues, and escalation"}, {"id": "7c58f387-87c2-4c57-883b-6765560a20d0", "type": "concept", "title": "Herbs, supplements, salt substitutes, antacids, binders, and medication–nutrient interactions"}, {"id": "4ebbe161-1214-4605-8d17-67e16eaabdf3", "type": "concept", "title": "Nephrology/RDN coordination, monitoring frequency, education, and shared decisions"}]}]}, {"id": "ddf8b173-4532-4117-866f-5121e4304569", "type": "topic", "title": "Medication–Nutrient and Supplement Interactions", "description": "Medication review is part of nutrition assessment because drugs can alter appetite, absorption, metabolism, laboratory values, and dietary safety.", "children": [{"id": "b3e4cfcd-0dbd-4c12-b929-513535b1daed", "type": "subtopic", "title": "Systematic review", "description": "Students reconcile prescription, over-the-counter, herbal, and supplement use.", "children": [{"id": "ea3ddffd-4721-4b31-ba64-24284849b4c7", "type": "concept", "title": "Indication, dose, route, schedule, formulation, adherence, allergies, and organ function"}, {"id": "253d3ff9-0c08-4adc-84a1-a4f5541b810f", "type": "concept", "title": "Appetite, taste, dry mouth, nausea, motility, glucose, weight, and electrolyte effects"}, {"id": "20753677-1798-4094-b215-d62df5ad3f48", "type": "concept", "title": "Temporal relationships, duplicate products, credible interaction tools, and pharmacist consultation"}]}, {"id": "63aad598-479a-41eb-bdc8-91f2cf5793f6", "type": "subtopic", "title": "Common interaction families", "description": "Students learn mechanisms and communication principles rather than memorizing isolated pairs.", "children": [{"id": "312d667b-b1a8-40f7-b844-edd87e539e52", "type": "concept", "title": "Chelation/binding, gastric pH, enzyme/transporter effects, and food-dependent absorption"}, {"id": "f3ea9812-27cf-4d60-8205-43821b9b341c", "type": "concept", "title": "Warfarin/vitamin K consistency, grapefruit interactions, levothyroxine timing, metformin/B12, and diuretics/electrolytes"}, {"id": "8f64e9c8-d2fb-45f7-abfc-30a864d3b389", "type": "concept", "title": "Tube-medication context, high-risk drugs, monitoring, and documentation"}]}, {"id": "9ea0a477-2bab-4ab8-8bb8-7ef31f7a3c85", "type": "subtopic", "title": "Supplement safety", "description": "Students evaluate need, evidence, quality, dose, duration, and risk.", "children": [{"id": "b193bb88-9ab2-46c6-b5b4-39e1be99bd15", "type": "concept", "title": "Third-party testing, contamination/adulteration, proprietary blends, and misleading claims"}, {"id": "3116c483-8b6e-4b3c-b474-746b737bf075", "type": "concept", "title": "ULs, renal/hepatic disease, anticoagulation, pregnancy, surgery, and immunocompromise"}, {"id": "19962220-ed6f-445a-b5e0-72af9828fb68", "type": "concept", "title": "Shared medication list, adverse-event reporting, deprescribing conversations, and referral"}]}]}, {"id": "c9804e44-1a47-438e-b4b1-eee9c07d6a5c", "type": "topic", "title": "Documentation, Counseling, and Interprofessional Care", "description": "Clear documentation and respectful communication turn a sound nutrition plan into coordinated care.", "children": [{"id": "dbb1435c-3cf9-4d7d-8294-29ed821d3ede", "type": "subtopic", "title": "Clinical documentation", "description": "Students write notes that are concise, evidence-linked, and actionable.", "children": [{"id": "1b14f0f8-990c-42cc-aafe-02da5d58d28b", "type": "concept", "title": "ADIME and SOAP structures; relevant positives/negatives; data provenance"}, {"id": "f06d30fd-5da7-478d-a774-802b5d6cc4f8", "type": "concept", "title": "PES statements, intervention rationale, calculations, goals, monitoring, and follow-up"}, {"id": "e911c6ea-ee5d-437f-845f-5de65fdbbbe4", "type": "concept", "title": "Avoiding copied-forward errors, stigmatizing language, unsupported certainty, and billing claims outside scope"}]}, {"id": "ccea7b77-ec98-40e3-bb47-8d633084390e", "type": "subtopic", "title": "Patient education and counseling", "description": "Students adapt communication to goals, literacy, language, culture, cognition, and readiness.", "children": [{"id": "fce92470-f853-4534-a3ee-eb16ce583218", "type": "concept", "title": "Plain language, teach-back, motivational interviewing foundations, and shared decision-making"}, {"id": "8de4380d-11bd-4a82-a7b0-7daa7b31aaea", "type": "concept", "title": "Culturally responsive meal translation, accessibility, interpreters, and caregiver involvement"}, {"id": "d94816a7-e01c-4544-81f8-81e3a1883c96", "type": "concept", "title": "Realistic action plans, barriers, autonomy, trauma-informed care, and referral"}]}, {"id": "f451800d-5efb-4058-8456-7c874e54e56d", "type": "subtopic", "title": "Team communication and transitions", "description": "Students practice role clarity and closed-loop follow-through.", "children": [{"id": "70b3ab00-97c3-45e5-b122-1689bac59f17", "type": "concept", "title": "Interprofessional roles, rounds, consult questions, escalation, and conflict management"}, {"id": "e4dd9543-4bf2-4eee-a295-a6db3c20ecf4", "type": "concept", "title": "Discharge reconciliation, diet orders, supplements, equipment, access, and appointments"}, {"id": "ed7149d9-d0af-47cd-8e53-101cbc0464b6", "type": "concept", "title": "Handoff summary, contingency criteria, follow-up ownership, and continuity"}]}]}, {"id": "6801accb-eef7-4bb2-81d8-d73d7ecd8e2b", "type": "topic", "title": "Clinical Case Study and Evidence-to-Decision Capstone", "description": "The capstone integrates the entire course in a deidentified case and rewards transparent reasoning, uncertainty, safety, and person-centered feasibility.", "children": [{"id": "fb2ee3ef-388a-4cac-ab78-577f00cfe707", "type": "subtopic", "title": "Case synthesis", "description": "Students create a concise, prioritized clinical picture from incomplete and changing information.", "children": [{"id": "d6eab9ab-0f64-4a75-8828-338f8db84079", "type": "concept", "title": "Timeline, problem representation, nutrition assessment, diagnoses, and competing risks"}, {"id": "0f7b0dbc-2d98-4261-9517-1268071c6b51", "type": "concept", "title": "Calculation assumptions, guideline fit, patient goals, equity and access"}, {"id": "7cb673a3-ee7c-4254-9131-02c0dc040661", "type": "concept", "title": "Alternative explanations, missing data, red flags, and consultation needs"}]}, {"id": "0b8dff3e-9de2-4400-bc0c-d151bde1ab18", "type": "subtopic", "title": "Evidence appraisal", "description": "Students find and judge guidance relevant to the actual decision.", "children": [{"id": "000e5e42-654e-476a-aafc-cbab3ed1cb5f", "type": "concept", "title": "PICO question, search strategy, guideline currency, systematic reviews, and primary studies"}, {"id": "51b38e8d-5b4c-4675-a987-2f04b3329401", "type": "concept", "title": "Risk of bias, certainty, directness, magnitude, conflicts, and generalizability"}, {"id": "8e178aa1-51f3-4f5b-95ed-b87c7f6831d0", "type": "concept", "title": "Recommendation strength, local policy, feasibility, preferences, and transparent rationale"}]}, {"id": "3d877fc0-ae6e-4ed5-9e02-21e14b26ec80", "type": "subtopic", "title": "Plan, presentation, and reflection", "description": "Students communicate and revise a safe care plan.", "children": [{"id": "27c33429-34e7-4dc8-9639-45f521ae39f5", "type": "concept", "title": "Intervention options, monitoring matrix, adverse-effect surveillance, and stop rules"}, {"id": "3b15ef35-7f6a-46ac-87d0-9f8ed23cb4e9", "type": "concept", "title": "ADIME note, oral case conference, visual data, questions, and closed-loop follow-up"}, {"id": "bfadb55d-6059-4ceb-8993-bcc451b526b4", "type": "concept", "title": "Peer critique, self-audit, scope limits, and revision after new clinical information"}]}]}], "dbBacked": true}$mnt1json$::jsonb,
