update public.learning_paths
set
  title = 'Medical Nutrition Therapy I',
  goal = 'Medical Nutrition Therapy I',
  summary = 'Foundational clinical nutrition care for common chronic and gastrointestinal conditions. Students apply the Nutrition Care Process to deidentified and simulated cases, integrate pathophysiology with assessment and intervention, interpret trends rather than isolated values, communicate across disciplines, and justify decisions using current evidence and the patient''s goals, culture, resources, and clinical trajectory.',
  data = $mnt1json${"slug": "medical-nutrition-therapy-i", "title": "Medical Nutrition Therapy I", "description": "Foundational clinical nutrition care for common chronic and gastrointestinal conditions. Students apply the Nutrition Care Process to deidentified and simulated cases, integrate pathophysiology with assessment and intervention, interpret trends rather than isolated values, communicate across disciplines, and justify decisions using current evidence and the patient's goals, culture, resources, and clinical trajectory.", "topics": [{"id": "0b2a5a6d-e727-4255-9cca-8580208bcf9c", "type": "topic", "title": "Nutrition Care Process and Clinical Reasoning", "description": "The Nutrition Care Process gives students a repeatable, person-centered way to move from data to a defensible diagnosis, intervention, and monitoring plan.", "children": [{"id": "5c90b22a-fc44-4747-9eac-145d108dbfdf", "type": "subtopic", "title": "Assessment-to-decision workflow", "description": "Students learn to organize information around a clinical decision rather than merely collect facts.", "children": [{"id": "03a8fcef-ad8c-47e9-98c7-0b25757517d0", "type": "concept", "title": "Screening versus comprehensive assessment; referral triggers and urgency"}, {"id": "3b9ed3b6-0f04-4d59-965b-e667338f3014", "type": "concept", "title": "Problem representation, differential explanations, missing data, and prioritization"}, {"id": "63cc2259-328e-4110-bc46-c8a9dac01326", "type": "concept", "title": "Patient goals, feasibility, benefit–burden balance, and reassessment"}]}, {"id": "5b6ea6a1-9a74-4329-b892-2ab5b2af3d0d", "type": "subtopic", "title": "Nutrition diagnosis and PES statements", "description": "Students connect a specific problem to a modifiable cause and measurable evidence.", "children": [{"id": "2c5ad6d1-9e9b-4c9e-b4bc-29bf58d5969a", "type": "concept", "title": "Standardized terminology and diagnostic domains"}, {"id": "703fe477-3dca-4d6c-a3c8-a947e36663b5", "type": "concept", "title": "Problem–etiology–signs/symptoms logic; avoiding medical diagnosis outside scope"}, {"id": "d7a12663-a4d9-4629-9004-b09d65f7c775", "type": "concept", "title": "Prioritizing diagnoses and revising them when evidence changes"}]}, {"id": "939233cf-b08b-4f39-ac1b-5d1a27b135b7", "type": "subtopic", "title": "Intervention, monitoring, and evaluation", "description": "Students translate reasoning into measurable action and learn from response.", "children": [{"id": "60800cb1-4108-4b52-8e3e-3cf27b15dd50", "type": "concept", "title": "Food/nutrient delivery, education, counseling, coordination, and referral"}, {"id": "680def4b-cc71-4c24-aa67-2206a2cb3b41", "type": "concept", "title": "SMART outcomes, indicators, time frames, targets, and contingency rules"}, {"id": "0a89acf4-4d30-4208-a6d8-7c28ab5cfe8a", "type": "concept", "title": "Outcome interpretation, adherence barriers, unintended effects, and plan revision"}]}]}, {"id": "a37b1bfa-b816-4af5-9a37-2d860c72e090", "type": "topic", "title": "Comprehensive Nutrition Assessment and NFPE", "description": "Clinical nutrition assessment integrates history, intake, anthropometry, physical findings, function, laboratory trends, and social context; no single measure is sufficient.", "children": [{"id": "49e73494-07b5-4fdc-b485-069b29353d77", "type": "subtopic", "title": "History, intake, and context", "description": "Students elicit clinically useful information respectfully and efficiently.", "children": [{"id": "f340bcfa-f506-4d4e-9c8e-b5ffc2c72fd6", "type": "concept", "title": "Diet history, appetite, symptoms, food allergies, supplements, alcohol, and feeding ability"}, {"id": "1914de62-d717-4b67-9ad1-0ff13a609b93", "type": "concept", "title": "Disease course, procedures, medications, functional status, and prior nutrition care"}, {"id": "c359a666-c3c0-44cb-a838-72cfeed9e09e", "type": "concept", "title": "Food security, culture, language, health literacy, housing, transport, and support"}]}, {"id": "4af2983c-81cc-4339-96ed-4b6cdc104cb6", "type": "subtopic", "title": "Anthropometry and laboratory interpretation", "description": "Students recognize trends, confounding, measurement error, and fluid effects.", "children": [{"id": "8c91cfa6-e860-4100-8c53-485bb324e292", "type": "concept", "title": "Height, weight trajectory, BMI context, growth history, waist and body-composition limits"}, {"id": "77669326-5d2d-464a-9984-a7964e62e64f", "type": "concept", "title": "Fluid shifts, edema, amputation adjustments, scale variation, and usual versus dry weight"}, {"id": "21395025-912b-47c8-ae8c-44b0a0c8a689", "type": "concept", "title": "Laboratory trends, inflammation, renal/hepatic effects, reference ranges, and false precision"}]}, {"id": "965c91f2-b345-4302-8119-a3475d11814f", "type": "subtopic", "title": "Nutrition-focused physical examination", "description": "Students use inspection and appropriate examination findings within training and supervision.", "children": [{"id": "74faf5e2-b0ac-4fd7-9f23-b245f7ed882c", "type": "concept", "title": "Muscle and subcutaneous-fat loss sites; bilateral comparison and baseline variation"}, {"id": "a571dec5-6a4a-4a21-97f8-4e65217a6768", "type": "concept", "title": "Edema, oral health, skin/hair/nails, functional indicators, and micronutrient clues"}, {"id": "9996ef72-75c5-4fcb-8379-0d01054785f8", "type": "concept", "title": "Consent, infection control, trauma-informed practice, documentation, and referral"}]}]}, {"id": "464a8025-297f-4ea9-88b5-3cede5799c90", "type": "topic", "title": "Energy, Protein, Fluid, and Micronutrient Requirements", "description": "Requirement estimates are hypotheses that must be checked against clinical course, intake, losses, organ function, and response.", "children": [{"id": "51d29f5f-8ccf-481e-8337-8220746a6dee", "type": "subtopic", "title": "Energy estimation", "description": "Students select and critique estimation methods rather than treating an equation as truth.", "children": [{"id": "6fb3c1a6-af4c-4aba-8876-bf41e09de16c", "type": "concept", "title": "Resting expenditure, stress/activity context, indirect calorimetry overview"}, {"id": "39f370f7-b7bb-4cd6-b72e-7d216c2a29d6", "type": "concept", "title": "Predictive equations, weight selection, obesity considerations, and sensitivity analysis"}, {"id": "092b2dc0-9c05-4241-8616-dd682cc0876c", "type": "concept", "title": "Intake adequacy, weight/function trends, glycemia, and iterative adjustment"}]}, {"id": "11660b79-cba8-47ff-afc9-581b8ece11df", "type": "subtopic", "title": "Protein and nitrogen", "description": "Students link protein goals to illness severity, healing, kidney/liver context, and energy adequacy.", "children": [{"id": "b2f59ac3-77f4-4932-aa2d-8f610a6aca55", "type": "concept", "title": "Protein turnover, nitrogen balance limitations, losses, wounds, and catabolism"}, {"id": "9130e522-95b3-4b91-8402-5115ea72f676", "type": "concept", "title": "Actual/ideal/adjusted weight controversies and guideline-specific assumptions"}, {"id": "8a0224af-8ab8-4bf8-84e2-33b29abdb5ca", "type": "concept", "title": "Food-first strategies, oral supplements, distribution, tolerance, and monitoring"}]}, {"id": "63c8475d-b3e1-4142-b4f1-e4019a07eb32", "type": "subtopic", "title": "Fluid and micronutrients", "description": "Students build individualized plans using intake, output, losses, medications, and organ function.", "children": [{"id": "9cb3260e-bf8c-4400-a54f-2d2989835562", "type": "concept", "title": "Maintenance concepts, fever, drains, GI losses, edema, and fluid restrictions"}, {"id": "52e4670c-4a8f-4e50-83e8-0a59b417d735", "type": "concept", "title": "Sodium, potassium, magnesium, phosphorus, calcium, acid–base context, and repletion boundaries"}, {"id": "c6f7dd02-87c5-4f4f-8c27-2d1f59d8f079", "type": "concept", "title": "Deficiency risk, food sources, supplementation safety, toxicity, and interaction checks"}]}]}, {"id": "8966eb3e-4c1c-4d31-b77b-a1a18e9807c4", "type": "topic", "title": "Malnutrition, Sarcopenia, and Refeeding Risk", "d