ss"}, {"id": "3b77e4d9-1e36-4062-90c9-06b0758c6b70", "type": "concept", "title": "Functional rehabilitation, interdisciplinary care, and realistic outcome measures"}, {"id": "e300716a-52fa-4ecd-b15d-b65c3e45439e", "type": "concept", "title": "Discharge risk, supply continuity, teach-back, referrals, and follow-up ownership"}]}]}, {"id": "0175008a-895f-4165-a28a-15e2332617ba", "type": "topic", "title": "Diabetes and Glycemic Management", "description": "MNT for diabetes is individualized and coordinated with medications, glucose monitoring, activity, culture, resources, and the person's priorities.", "children": [{"id": "5e8ab471-f078-4ec4-9e9f-0db24ff498e2", "type": "subtopic", "title": "Pathophysiology and assessment", "description": "Students differentiate diabetes types and identify data needed for safe care.", "children": [{"id": "db4e306e-b7ed-43c9-a3c7-215627c1a5d1", "type": "concept", "title": "Type 1, type 2, gestational and secondary diabetes; insulin resistance and deficiency"}, {"id": "c93deaf0-0b34-43a7-94bc-70f3713894f1", "type": "concept", "title": "A1C, glucose patterns, CGM metrics, hypoglycemia, medications, kidney disease, and complications"}, {"id": "5d637747-1267-466b-9dd0-9dfee55fca31", "type": "concept", "title": "Food access, distress, numeracy, work schedule, disordered eating risk, and readiness"}]}, {"id": "bf26d9d6-7d50-4469-bde9-443e9b85b7fb", "type": "subtopic", "title": "Nutrition intervention", "description": "Students use pattern-based and carbohydrate-aware strategies without imposing one universal diet.", "children": [{"id": "66f6fcee-434f-47da-b51f-c97a7d37b768", "type": "concept", "title": "Carbohydrate amount, quality, timing, fiber, beverages, fats, protein, and overall patterns"}, {"id": "52465747-0e4b-4df7-bfab-984755a208c6", "type": "concept", "title": "Carbohydrate counting, plate methods, consistent-carbohydrate approaches, labels, and dining out"}, {"id": "2b092f94-b0f8-48ce-8154-56bf0bb09c2d", "type": "concept", "title": 