ve—restriction.", "children": [{"id": "cda39091-7a0b-4907-acd9-7492347ca959", "type": "subtopic", "title": "Kidney function and assessment", "description": "Students connect filtration, fluid and electrolyte regulation, and acid–base balance to nutrition.", "children": [{"id": "254c8de3-de80-4f64-80d7-fa069cfb65e1", "type": "concept", "title": "AKI versus CKD, eGFR and albuminuria trends, diabetes/hypertension, and progression"}, {"id": "d5f6f23f-f6c5-49f2-986b-c7d22c26fa07", "type": "concept", "title": "Volume status, blood pressure, urine output, appetite, symptoms, and medication review"}, {"id": "a69bc273-a6aa-4a3b-b231-545a46d68c69", "type": "concept", "title": "Potassium, phosphorus, bicarbonate, calcium/PTH context, anemia, and laboratory limitations"}]}, {"id": "238d7040-e988-4e59-bd26-8d5c79966c52", "type": "subtopic", "title": "Nutrition priorities by stage", "description": "Students balance adequacy, metabolic goals, and preservation of function.", "children": [{"id": "d6646e38-4959-4dd4-82c4-6cabaf063a16", "type": "concept", "title": "Energy and protein context before dialysis; sodium and blood-pressure management"}, {"id": "48854116-61e9-4c22-a818-e2fa08cab44e", "type": "concept", "title": "Potassium and phosphorus individualized to laboratory trends and food sources"}, {"id": "636f36e9-b1aa-4cc6-ab12-24860e03ae4a", "type": "concept", "title": "Plant-forward patterns, food additives, labels, diabetes integration, and cultural preferences"}]}, {"id": "febd7517-cc08-4c0d-8977-218c58dc3c25", "type": "subtopic", "title": "Safety and referral", "description": "Students recognize when kidney nutrition exceeds introductory scope.", "children": [{"id": "7396e7f5-c86a-4022-b7b3-3b881fb182e1", "type": "concept", "title": "Hyperkalemia symptoms/context, rapidly changing kidney function, severe fluid issues, and escalation"}, {"id": "7c58f387-87c2-4c57-883b-6765560a20d0", "type": "concept", "title": "Herbs, supplements, salt substitutes, antacids, binders, and medication–nutrient interactions"}, {"id": "4ebbe161-1214-4605-8d17-67e16eaabdf3", "type": "concept", "title": "Nephrology/RDN coordination, monitoring frequency, education, and shared decisions"}]}]}, {"id": "ddf8b173-4532-4117-866f-5121e4304569", "type": "topic", "title": "Medication–Nutrient and Supplement Interactions", "description": "Medication review is part of nutrition assessment because drugs can alter appetite, absorption, metabolism, laboratory values, and dietary safety.", "children": [{"id": "b3e4cfcd-0dbd-4c12-b929-513535b1daed", "type": "subtopic", "title": "Systematic review", "description": "Students reconcile prescription, over-the-counter, herbal, and supplement use.", "children": [{"id": "ea3ddffd-4721-4b31-ba64-24284849b4c7", "type": "concept", "title": "Indication, dose, route, schedule, formulation, adherence, allergies, and organ function"}, {"id": "253d3ff9-0c08-4adc-84a1-a4f5541b810f", "type": "concept", "title": "Appetite, taste, dry mouth, nausea, motility, glucose, weight, and electrolyte effects"}, {"id": "20753677-1798-4094-b215-d62df5ad3f48", "type": "concept", "title": "Temporal relationships, duplicate products, credible interaction tools, and pharmacist consultation"}]}, {"id": "63aad598-479a-41eb-bdc8-91f2cf5793f6", "type": "subtopic", "title": "Common interaction families", "description": "Students learn mechanisms and communication principles rather than memorizing isolated pairs.", "children": [{"id": "312d667b-b1a8-40f7-b844-edd87e539e52", "type": "concept", "title": "Chelation/binding, gastric pH, enzyme/transporter effects, and food-dependent absorption"}, {"id": "f3ea9812-27cf-4d60-8205-43821b9b341c", "type": "concept", "title": "Warfarin/vitamin K consistency, grapefruit interactions, levothyroxine timing, metformin/B12, and diuretics/electrolytes"}, {"id": "8f64e9c8-d2fb-45f7-abfc-30a864d3b389", "type": "concept", "title": "Tube-medication context, high-risk drugs, monitoring, and documentation"}]}, {"id": "9ea0a477-2bab-4ab